# Exact bivariate polynomial coefficients, exponent pairs (u exponent,v exponent).
def multiply(p,q):
 out={}
 for (i,j),a in p.items():
  for (k,l),b in q.items():out[(i+k,j+l)]=out.get((i+k,j+l),F(0))+a*b
 return{k:v for k,v in out.items()if v!=0}
def evaluate(p,u,v):return sum((a*u**i*v**j for(i,j),a in p.items()),F(0))
def enc(p):return{f'{i},{j}':str(v)for(i,j),v in sorted(p.items())}
